import{_ as a,o,c as t,a5 as c}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Plan — Update Workspace Profile (FR 3.4.14)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-14-update-workspace-profile/plan.md","filePath":"feature/agency-workspace/3-4-14-update-workspace-profile/plan.md"}'),n={name:"feature/agency-workspace/3-4-14-update-workspace-profile/plan.md"};function d(l,e,i,s,r,p){return o(),t("div",null,[...e[0]||(e[0]=[c(`<h1 id="plan-—-update-workspace-profile-fr-3-4-14" tabindex="-1">Plan — Update Workspace Profile (FR 3.4.14) <a class="header-anchor" href="#plan-—-update-workspace-profile-fr-3-4-14" aria-label="Permalink to &quot;Plan — Update Workspace Profile (FR 3.4.14)&quot;">​</a></h1><p>&gt; Liên kết: <a href="./spec.html">spec.md</a> — cho MANAGER cập nhật thông tin/settings/logo của Workspace.</p><h2 id="_1-pham-vi-ky-thuat" tabindex="-1">1. Phạm vi kỹ thuật <a class="header-anchor" href="#_1-pham-vi-ky-thuat" aria-label="Permalink to &quot;1. Phạm vi kỹ thuật&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Repo</td><td><code>brandhub-business-service</code></td></tr><tr><td>File implement</td><td><code>WorkspaceServiceImpl.updateSettings()</code>, <code>WorkspaceServiceImpl.updateLogo()</code></td></tr><tr><td>File đã có</td><td><code>WorkspaceController</code> (<code>PATCH /{workspaceId}/settings</code>, <code>POST /{workspaceId}/logo</code>), <code>UpdateWorkspaceSettingsRequest</code>, <code>FileStorageService</code></td></tr></tbody></table><h2 id="_2-api-contract-final" tabindex="-1">2. API Contract (final) <a class="header-anchor" href="#_2-api-contract-final" aria-label="Permalink to &quot;2. API Contract (final)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PATCH /api/v1/workspaces/{workspaceId}/settings</span></span>
<span class="line"><span>Body: { name?, timezone?, defaultPlatforms?, industry?, companySize?, website?, phone?, location? }</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;WorkspaceResponse&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POST /api/v1/workspaces/{workspaceId}/logo</span></span>
<span class="line"><span>Body: multipart/form-data, field &quot;file&quot;</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;WorkspaceResponse&gt;</span></span></code></pre></div><p>Cả 2 endpoint bảo vệ bởi <code>@RequireRole({MemberRole.MANAGER})</code>. Không lệch spec.md.</p><h2 id="_3-data-model" tabindex="-1">3. Data Model <a class="header-anchor" href="#_3-data-model" aria-label="Permalink to &quot;3. Data Model&quot;">​</a></h2><ul><li><code>UPDATE workspaces</code>: set <code>name</code> (nếu không blank), merge <code>settings</code> JSON (<code>timezone</code>/<code>defaultPlatforms</code>, field null giữ nguyên), set <code>industry</code>/<code>companySize</code>/<code>website</code>/<code>phone</code>/<code>location</code> (nếu request có truyền), <code>updatedAt = now()</code>.</li><li>Logo: đọc bytes file → <code>fileStorageService.uploadWorkspaceLogo</code> → set <code>logoUrl</code>, <code>updatedAt = now()</code>.</li><li>Không migration.</li></ul><h2 id="_4-luong-xu-ly" tabindex="-1">4. Luồng xử lý <a class="header-anchor" href="#_4-luong-xu-ly" aria-label="Permalink to &quot;4. Luồng xử lý&quot;">​</a></h2><p><strong>Flow A — settings:</strong></p><ol><li><code>@RequireRole(MANAGER)</code> chặn ở tầng controller.</li><li><code>findWorkspaceOrThrow</code> → 404.</li><li>Merge field theo request (partial update, field null giữ nguyên).</li><li>Save.</li></ol><p><strong>Flow B — logo:</strong></p><ol><li><code>@RequireRole(MANAGER)</code> chặn.</li><li><code>findWorkspaceOrThrow</code> → 404.</li><li><code>file.getBytes()</code> — <code>IOException</code> → 400 <code>FILE_READ_ERROR</code>.</li><li>Upload storage → set <code>logoUrl</code>.</li></ol><h2 id="_5-dependencies" tabindex="-1">5. Dependencies <a class="header-anchor" href="#_5-dependencies" aria-label="Permalink to &quot;5. Dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chiều</th><th>Mô tả</th></tr></thead><tbody><tr><td>Chặn bởi</td><td><code>Workspace</code> entity, <code>FileStorageService</code> (đã có)</td></tr><tr><td>Bị chặn</td><td>Không</td></tr></tbody></table><h2 id="_6-rui-ro-ky-thuat" tabindex="-1">6. Rủi ro kỹ thuật <a class="header-anchor" href="#_6-rui-ro-ky-thuat" aria-label="Permalink to &quot;6. Rủi ro kỹ thuật&quot;">​</a></h2><ul><li><strong>Đổi <code>timezoneConfig</code> không cảnh báo ảnh hưởng Task/Livestream đã lên lịch</strong> (Edge case mục 7 trong spec.md) — chưa có validate/cảnh báo ở BE, cần FE tự xử lý cảnh báo trước khi gọi API, hoặc bổ sung sau.</li><li><strong>Update qua PATCH true-partial</strong> (field null giữ nguyên) khác với Update Agency Profile (dùng PUT, full-update) — 2 pattern khác nhau giữa Agency và Workspace, cần lưu ý khi FE tích hợp cả 2.</li><li><strong><code>@RequireRole</code> không check đúng &quot;MANAGER của chính workspace này&quot; nếu aspect chỉ check role chung</strong> — cần xác nhận aspect có resolve đúng theo <code>{workspaceId}</code> path variable hay không (khác với <code>getWorkspace</code>/<code>listMembers</code> phải check thủ công vì lý do này).</li></ul>`,18)])])}const g=a(n,[["render",d]]);export{u as __pageData,g as default};
